text(await tools.apply_patch("*** Begin Patch
*** Update File: /Volumes/aro/projects/prose_generation/enrichment/bible/work/s087/ehlikitap-images.sol.max.session-20261005/sec10/annotations.jsonl
@@
-{"id":"S087-INC-MTF-001","gelenek":"incil","tur":"motif","ayet":"87:1|87:15","islev":"destek","iliski":"lafzi","durum":"acik","kat":"ek","metin":"Matta 6:9'daki dua {el:ἁγιασθήτω τὸ ὄνομά σου, tr:hagiasthēto to onoma sou, gloss:adın kutsal kılınsın, source:SBLGNT:Matt.6.9} diye başlar. Vahiy 15:4'ün ilahisi de Tanrı'nın adının yüceltilmesini onun kutsallığıyla bağlar. Böylece adı anmak, İncil katmanında da duanın ve kutsallık ilanının içindedir.","kaynak":"SBLGNT:Matt.6.9|SBLGNT:Rev.15.4","paragraf":40,"capa":"Tesbih bu yükseltmenin içeriğini verir","bag":"benzerlik","tarihleme":"kuran_oncesi","nusha":"yunanca_ahit"}
+{"id":"S087-INC-MTF-001","gelenek":"incil","tur":"motif","ayet":"87:1|87:15","islev":"destek","iliski":"lafzi","durum":"acik","kat":"ek","metin":"Matta 6:9'daki dua {el:ἁγιασθήτω τὸ ὄνομά σου, tr:hagiasthēto to onoma sou, gloss:adın kutsal kılınsın, source:SBLGNT:Matt.6.9} diye başlar. Meryem de Tanrı'nın adını kutsal ilan eder (Luka 1:49); Vahiy 15:4'ün ilahisi, adın yüceltilmesini onun kutsallığıyla bağlar. Böylece adı anmak, İncil katmanında duanın ve kutsallık ilanının içindedir.","kaynak":"SBLGNT:Matt.6.9|SBLGNT:Luke.1.49|SBLGNT:Rev.15.4","paragraf":40,"capa":"Tesbih bu yükseltmenin içeriğini verir","bag":"benzerlik","tarihleme":"kuran_oncesi","nusha":"yunanca_ahit"}
+{"id":"S087-INC-MTF-005","gelenek":"incil","tur":"motif","ayet":"87:1|87:15","islev":"aciklama","iliski":"lafzi","durum":"acik","kat":"ek","metin":"Yuhanna 12:28'de İsa 'Baba, adını yücelt' diye dua eder; gökten gelen ses adın yüceltildiğini bildirir. İbranilere 13:15 ise Tanrı'nın adını açıkça söyleyen dudakları sürekli bir övgü kurbanı olarak niteler. Biri dua, diğeri toplu ibadet diliyle adın onurlandırılmasını somutlaştırır.","kaynak":"SBLGNT:John.12.28|SBLGNT:Heb.13.15","paragraf":40,"capa":"Tesbih bu yükseltmenin içeriğini verir","bag":"benzerlik","tarihleme":"kuran_oncesi","nusha":"yunanca_ahit"}
@@
 {"id":"S087-INC-MTF-004","gelenek":"incil","tur":"motif","ayet":"87:16-17","islev":"sonuc","iliski":"tematik","durum":"acik","kat":"ek","metin":"Matta 6:19-21 yerdeki hazinenin çürüdüğünü, göktekinin kalıcı olduğunu ve yüreğin hazinesinin bulunduğu yerde olacağını söyler. Böylece yakın hayatı seçmek yalnız kısa ömürlü bir mala yönelmek değil, yüreğin bağlandığı yeri belirlemektir.","kaynak":"SBLGNT:Matt.6.19|SBLGNT:Matt.6.20|SBLGNT:Matt.6.21","paragraf":41,"capa":"Surenin iki ucunda bu iki kelime durur","bag":"benzerlik","tarihleme":"kuran_oncesi","nusha":"yunanca_ahit"}
+{"id":"S087-INC-MTF-006","gelenek":"incil","tur":"motif","ayet":"87:1|87:16","islev":"aciklama","iliski":"tematik","durum":"acik","kat":"ek","metin":"Meryem'in ilahisi, Tanrı'nın hükümdarları tahtlarından indirdiğini ve alçakgönüllüleri yükselttiğini söyler (Luka 1:52). Matta 23:12'de de kendini yükseltenin alçaltılacağı, alçalanın yükseltileceği belirtilir. Şerhteki yükseklik ve alçaklık ekseni, bu iki Hristiyan metinde ahlaki tersine dönüşün dili olur.","kaynak":"SBLGNT:Luke.1.52|SBLGNT:Matt.23.12","paragraf":41,"capa":"Surenin iki ucunda bu iki kelime durur","bag":"benzerlik","tarihleme":"kuran_oncesi","nusha":"yunanca_ahit"}
*** End Patch"));

text(await tools.apply_patch("*** Begin Patch
*** Add File: /Volumes/aro/projects/prose_generation/enrichment/bible/work/s087/ehlikitap-images.sol.max.session-20261005/sec10/verdicts.jsonl
+{"connection_id":"BC-3d009d09131ac5e636dc","ref":"Augustine, City of God 14.28","status":"unavailable","reason":"The local snapshot has no City of God text; its two-cities wording cannot be checked here.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-19ff5db70e40cfb9a36b","ref":"Didache 10:2","status":"unavailable","reason":"The local snapshot has no Didache text to verify this prayer wording.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-38106e98d84faee415f4","ref":"Didache 8:2","status":"unavailable","reason":"The local snapshot has no Didache text to check the prayer instruction.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-5e1d4169f40b14e10ee4","ref":"Epistle to Diognetus 5:9","status":"unavailable","reason":"The local snapshot lacks this epistle's text; the citizenship wording is unverified.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-730ac5cebcd18ab60c12","ref":"Ignatius, To the Romans 6:1","status":"unavailable","reason":"The local snapshot lacks Ignatius here; the claimed contrast cannot be verified.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-09cdc151cb2e62623b21","ref":"Origen, Homilies on Luke 8","status":"unavailable","reason":"The local snapshot lacks Origen's homily; its interpretation cannot be checked.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-dee47aa02211daf389b6","ref":"Origen, On Prayer 23","status":"unavailable","reason":"The local snapshot lacks this Origen passage; its stated reading cannot be checked.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-388174e024fb50f5a0ef","ref":"SBLGNT:1Cor.7.31","status":"rejected","reason":"The verse says the world's form passes, a valid but less pointed instance of transience than the explicit world/endurance antithesis in 1 John 2:17 used at paragraph 41.","paragraphs":[],"evidence":["SBLGNT:1Cor.7.31"],"annotations":[]}
+{"connection_id":"BC-845066d20c848c0a842a","ref":"SBLGNT:1John.2.17","status":"accepted","reason":"The passing world and enduring doer of God's will directly clarify the near/enduring choice in paragraph 41.","paragraphs":[41],"evidence":["SBLGNT:2Cor.4.18","SBLGNT:1John.2.17"],"annotations":["S087-INC-MTF-003"]}
+{"connection_id":"BC-2af3af09d2cb548e4c7e","ref":"SBLGNT:1John.2.17","status":"accepted","reason":"The candidate's world-versus-endurance point is expressed with 2 Corinthians 4:18 in paragraph 41.","paragraphs":[41],"evidence":["SBLGNT:2Cor.4.18","SBLGNT:1John.2.17"],"annotations":["S087-INC-MTF-003"]}
+{"connection_id":"BC-aeace61924877bd5f547","ref":"SBLGNT:1Pet.5.6","status":"rejected","reason":"God exalting the humble is genuine, but this exhortation repeats the explicit status reversal represented by Luke 1:52 and Matthew 23:12 at paragraph 41.","paragraphs":[],"evidence":["SBLGNT:1Pet.5.6"],"annotations":[]}
+{"connection_id":"BC-e31457992b343cc21dd0","ref":"SBLGNT:1Tim.6.16","status":"rejected","reason":"Unapproachable light is present, but this verse says nothing of God's face or the punitive fire of 87:12; the paired Sinai and blessing texts distinguish those images more precisely.","paragraphs":[],"evidence":["SBLGNT:1Tim.6.16"],"annotations":[]}
+{"connection_id":"BC-5b218332edd37497508a","ref":"SBLGNT:1Tim.6.17","status":"rejected","reason":"The warning to rich people concerns uncertain wealth and haughtiness, an economic application beyond this paragraph's lexical high/low contrast; Matthew 6:19-21 states the chosen-value issue directly.","paragraphs":[],"evidence":["SBLGNT:1Tim.6.17"],"annotations":[]}
+{"connection_id":"BC-45a607ac32193392d816","ref":"SBLGNT:2Cor.4.18","status":"accepted","reason":"Visible temporary and unseen eternal things state the duration distinction attached to 87:16-17.","paragraphs":[41],"evidence":["SBLGNT:2Cor.4.18","SBLGNT:1John.2.17"],"annotations":["S087-INC-MTF-003"]}
+{"connection_id":"BC-dd2912d356abcb7167de","ref":"SBLGNT:2Cor.4.18","status":"accepted","reason":"The second proposal names the same verified temporal contrast, stated in paragraph 41's note.","paragraphs":[41],"evidence":["SBLGNT:2Cor.4.18","SBLGNT:1John.2.17"],"annotations":["S087-INC-MTF-003"]}
+{"connection_id":"BC-bbae0f1e7da0f536e3dc","ref":"SBLGNT:2Cor.4.6","status":"rejected","reason":"The light is specifically knowledge of glory in Christ's face; the paragraph's lexicon gloss concerns divine radiance and a different fire image, so this would blur the referent.","paragraphs":[],"evidence":["SBLGNT:2Cor.4.6"],"annotations":[]}
+{"connection_id":"BC-ad3a53a8de1d3715fcb6","ref":"SBLGNT:2Thess.1.8","status":"rejected","reason":"Flaming judgment fire is real, but paragraph 40 only mentions 87:12 through a root-based association; the verse adds no distinction to that high/name argument.","paragraphs":[],"evidence":["SBLGNT:2Thess.1.8"],"annotations":[]}
+{"connection_id":"BC-c520f41a0960f9950865","ref":"SBLGNT:2Thess.2.4","status":"rejected","reason":"This is an unnamed eschatological opponent, not Pharaoh or Moses's adversary; calling it a counter-narrative of Pharaoh would conflate distinct figures.","paragraphs":[],"evidence":["SBLGNT:2Thess.2.4"],"annotations":[]}
+{"connection_id":"BC-e607a7bc943822f4d983","ref":"SBLGNT:2Tim.3.8","status":"rejected","reason":"The verse names Jannes and Jambres as opponents of Moses but does not call them magicians or narrate their fate; it cannot by itself establish a contrary magicians' conversion account.","paragraphs":[],"evidence":["SBLGNT:2Tim.3.8"],"annotations":[]}
+{"connection_id":"BC-3c2cd8cff2fc2d9135c0","ref":"SBLGNT:2Tim.3.8","status":"rejected","reason":"It supplies two opponent names but not their identification as the Egyptian magicians in the opened verse; this tradition detail would require another witness.","paragraphs":[],"evidence":["SBLGNT:2Tim.3.8"],"annotations":[]}
+{"connection_id":"BC-daba7ea9e7ce56002971","ref":"SBLGNT:Acts.12.23","status":"rejected","reason":"Herod's failure to give God glory is a royal warning, but the verse itself lacks the crowd's divine acclamation; Isaiah 14 and Ezekiel 28 give the explicit self-deification needed at paragraph 42.","paragraphs":[],"evidence":["SBLGNT:Acts.12.23"],"annotations":[]}
+{"connection_id":"BC-fbe2cc46c1c8f086f151","ref":"SBLGNT:Acts.16.17","status":"rejected","reason":"A divining woman calls Paul God's servants; this is not the Moses-magicians contest, and the Most High title is not being arrogated by the diviner.","paragraphs":[],"evidence":["SBLGNT:Acts.16.17"],"annotations":[]}
+{"connection_id":"BC-bebb89d982be938eec3d","ref":"SBLGNT:Acts.17.24","status":"rejected","reason":"God not dwelling in handmade temples does not contradict Qur'an 24:36's houses where the name is recited; treating it as a counter-narrative would create a tension the cited texts do not state.","paragraphs":[],"evidence":["SBLGNT:Acts.17.24"],"annotations":[]}
+{"connection_id":"BC-be239f934808c02ef68c","ref":"SBLGNT:Acts.7.48","status":"rejected","reason":"The Most High not dwelling in handmade structures qualifies containment, which 1 Kings 8:27-29 already states in the source tradition behind the house image; 24:36 does not claim containment.","paragraphs":[],"evidence":["SBLGNT:Acts.7.48"],"annotations":[]}
+{"connection_id":"BC-6f85aef808ea7427f467","ref":"SBLGNT:Col.3.2","status":"accepted","reason":"The Greek explicitly opposes attention above to things on earth, illuminating the page's directional axis.","paragraphs":[41],"evidence":["SBLGNT:Col.3.2","SBLGNT:Phil.3.19","SBLGNT:Phil.3.20"],"annotations":["S087-INC-MTF-002"]}
+{"connection_id":"BC-9d826cc85a3742e13fec","ref":"SBLGNT:Col.3.2","status":"accepted","reason":"Its above/earth imperative is the same verified orientation point joined to Philippians 3:19-20.","paragraphs":[41],"evidence":["SBLGNT:Col.3.2","SBLGNT:Phil.3.19","SBLGNT:Phil.3.20"],"annotations":["S087-INC-MTF-002"]}
+{"connection_id":"BC-8a6a2482fec31cb553ad","ref":"SBLGNT:Eph.1.21","status":"rejected","reason":"The text speaks of Christ above cosmic powers and every named authority; it is a Christological rank claim, not the act of praising God's name or choosing enduring life.","paragraphs":[],"evidence":["SBLGNT:Eph.1.21"],"annotations":[]}
+{"connection_id":"BC-3fd0165e0a85cd2eb81a","ref":"SBLGNT:Heb.1.3","status":"rejected","reason":"The Son at the right hand of Majesty on high is a distinct Christological enthronement; its purification clause does not explain the surah's name/near-life axis.","paragraphs":[],"evidence":["SBLGNT:Heb.1.3"],"annotations":[]}
+{"connection_id":"BC-009b39b91206e5c8664c","ref":"SBLGNT:Heb.11.16","status":"rejected","reason":"A better heavenly country is a legitimate resonance, but Philippians 3:19-20 states earthly-mindedness against heavenly belonging more directly for paragraph 41.","paragraphs":[],"evidence":["SBLGNT:Heb.11.16"],"annotations":[]}
+{"connection_id":"BC-3fe1ecbd1ecc86679ec6","ref":"SBLGNT:Heb.11.25","status":"rejected","reason":"Hebrews treats Moses's choice of temporary pleasure, whereas paragraph 42 concerns his confrontation with Pharaoh and magicians; linking those episodes as one scene would misplace the point.","paragraphs":[],"evidence":["SBLGNT:Heb.11.25"],"annotations":[]}
+{"connection_id":"BC-7f30a49c0c9d1b091a87","ref":"SBLGNT:Heb.11.26","status":"rejected","reason":"Moses's comparison of Egypt's treasure with Christ's reproach is the letter's own theological reading, not the particular magicians scene or the name-praise image in paragraph 42.","paragraphs":[],"evidence":["SBLGNT:Heb.11.26"],"annotations":[]}
+{"connection_id":"BC-8866594f0f9fe36f0460","ref":"SBLGNT:Heb.12.29","status":"rejected","reason":"'God is consuming fire' is a worship warning echoing Deuteronomy 4:24, not the fire into which the wretched enter at 87:12; the distinction matters more than another fire parallel here.","paragraphs":[],"evidence":["SBLGNT:Heb.12.29"],"annotations":[]}
+{"connection_id":"BC-6e2ceefc615b5249aeb1","ref":"SBLGNT:Heb.13.14","status":"rejected","reason":"The coming city is a valid image of lasting hope, but the visible/eternal antithesis in 2 Corinthians 4:18 states paragraph 41's value contrast without importing a city image.","paragraphs":[],"evidence":["SBLGNT:Heb.13.14"],"annotations":[]}
+{"connection_id":"BC-d3849b61faa6eb9986a5","ref":"SBLGNT:Heb.13.15","status":"accepted","reason":"The Greek describes continual praise as lips confessing God's name, a concrete worship practice attached to paragraph 40.","paragraphs":[40],"evidence":["SBLGNT:John.12.28","SBLGNT:Heb.13.15"],"annotations":["S087-INC-MTF-005"]}
+{"connection_id":"BC-23cd01463e26694c3e92","ref":"SBLGNT:Heb.13.15","status":"accepted","reason":"Its confession-of-name point is explicitly expressed in the linked worship note.","paragraphs":[40],"evidence":["SBLGNT:John.12.28","SBLGNT:Heb.13.15"],"annotations":["S087-INC-MTF-005"]}
+{"connection_id":"BC-1d10ef4b87eab836daf6","ref":"SBLGNT:Heb.2.12","status":"rejected","reason":"Proclaiming the name in assembly is relevant but repeats the public name-praise already shown by Hebrews 13:15, which adds the sacrifice-of-praise interpretation.","paragraphs":[],"evidence":["SBLGNT:Heb.2.12"],"annotations":[]}
+{"connection_id":"BC-5db915aa72d429bdeecf","ref":"SBLGNT:Heb.7.1","status":"rejected","reason":"Hebrews does receive Melchizedek as priest of the Most High, but the verse adds no reading of the high title itself beyond Genesis 14:19 used at paragraph 39.","paragraphs":[],"evidence":["SBLGNT:Heb.7.1"],"annotations":[]}
+{"connection_id":"BC-53c4490b8dc5c8b8c1db","ref":"SBLGNT:Jas.4.10","status":"rejected","reason":"The humility/exaltation formula is genuine but duplicates the fuller royal and lowly reversal in Luke 1:52 and Matthew 23:12.","paragraphs":[],"evidence":["SBLGNT:Jas.4.10"],"annotations":[]}
+{"connection_id":"BC-043e5c745866aa9e2462","ref":"SBLGNT:John.12.25","status":"rejected","reason":"This is an individual life-loss paradox, while paragraph 41 names the near world's collective value; 1 John 2:17 speaks of the passing world directly.","paragraphs":[],"evidence":["SBLGNT:John.12.25"],"annotations":[]}
+{"connection_id":"BC-78dfb426fc45ce8bf343","ref":"SBLGNT:John.12.28","status":"accepted","reason":"Jesus's petition and the heavenly reply explicitly concern glorifying the Father's name, giving paragraph 40 a precise prayer scene.","paragraphs":[40],"evidence":["SBLGNT:John.12.28","SBLGNT:Heb.13.15"],"annotations":["S087-INC-MTF-005"]}
*** End Patch"));

text(await tools.apply_patch("*** Begin Patch
*** Update File: /Volumes/aro/projects/prose_generation/enrichment/bible/work/s087/ehlikitap-images.sol.max.session-20261005/sec10/verdicts.jsonl
@@
 {"connection_id":"BC-78dfb426fc45ce8bf343","ref":"SBLGNT:John.12.28","status":"accepted","reason":"Jesus's petition and the heavenly reply explicitly concern glorifying the Father's name, giving paragraph 40 a precise prayer scene.","paragraphs":[40],"evidence":["SBLGNT:John.12.28","SBLGNT:Heb.13.15"],"annotations":["S087-INC-MTF-005"]}
+{"connection_id":"BC-aa87f3592b27a34c1c2a","ref":"SBLGNT:John.14.13","status":"rejected","reason":"Prayer is in Jesus's name and glorifies the Father; that mediation differs from the surah's direct naming of the Lord, already compared through John 12:28.","paragraphs":[],"evidence":["SBLGNT:John.14.13"],"annotations":[]}
+{"connection_id":"BC-3abd88eb46603abdc594","ref":"SBLGNT:John.17.6","status":"rejected","reason":"Manifesting the Father's name concerns Jesus's revelation to disciples; it does not explain the commentary's proposed name-height etymology or its praise command.","paragraphs":[],"evidence":["SBLGNT:John.17.6"],"annotations":[]}
+{"connection_id":"BC-5e79b86136fb1f5323c7","ref":"SBLGNT:John.4.21","status":"rejected","reason":"Worship beyond a mountain or Jerusalem is not a counter-story to Qur'an 24:36, which permits name-recitation in houses without restricting worship to them.","paragraphs":[],"evidence":["SBLGNT:John.4.21"],"annotations":[]}
+{"connection_id":"BC-f9b5139e7766b59977f9","ref":"SBLGNT:John.5.44","status":"rejected","reason":"Human versus divine glory is a moral comparison but has neither the high divine title nor the self-deifying ruler of paragraph 42; Isaiah 14:14 is more exact.","paragraphs":[],"evidence":["SBLGNT:John.5.44"],"annotations":[]}
+{"connection_id":"BC-4d14fa0fc3b24f0d4b1a","ref":"SBLGNT:Luke.1.32","status":"rejected","reason":"'Son of the Most High' is a specifically Christological royal promise, not an usurped title like Pharaoh's; treating them as the same kind of royal claim would distort the verse.","paragraphs":[],"evidence":["SBLGNT:Luke.1.32"],"annotations":[]}
+{"connection_id":"BC-22e002011243245195f6","ref":"SBLGNT:Luke.1.46","status":"rejected","reason":"Mary magnifies the Lord, but this line contains no name or high/low reversal; Luke 1:49 and 1:52 supply the more precise aspects used in separate notes.","paragraphs":[],"evidence":["SBLGNT:Luke.1.46"],"annotations":[]}
+{"connection_id":"BC-9210220786b42067a767","ref":"SBLGNT:Luke.1.49","status":"accepted","reason":"The Mighty One's holy name joins greatness and holiness, expressed beside Matthew 6:9 and Revelation 15:4.","paragraphs":[40],"evidence":["SBLGNT:Matt.6.9","SBLGNT:Luke.1.49","SBLGNT:Rev.15.4"],"annotations":["S087-INC-MTF-001"]}
+{"connection_id":"BC-fc7470139669c319f42c","ref":"SBLGNT:Luke.1.49","status":"accepted","reason":"Mary's holy-name line is stated in the paragraph 40 annotation; the later reversal receives its own note at paragraph 41.","paragraphs":[40],"evidence":["SBLGNT:Matt.6.9","SBLGNT:Luke.1.49","SBLGNT:Rev.15.4"],"annotations":["S087-INC-MTF-001"]}
